<template>
  <AppWorkspacePanel class="receipt-workbench">
    <div class="workbench-toolbar"><div><h2>银行回单</h2><p>回单按“识别 → 复核 → 分摊 → 入账”处理；清除会保留审计历史。</p></div><el-upload :auto-upload="false" :show-file-list="false" accept=".pdf" :on-change="upload"><el-button type="primary">上传回单 PDF</el-button></el-upload></div>
    <div class="status-filter"><el-select v-model="statusFilter" clearable placeholder="全部状态"><el-option v-for="option in statusOptions" :key="option.value" :label="option.label" :value="option.value"/></el-select></div><el-table :data="filteredBatches" border><el-table-column prop="batch_number" label="批次号"/><el-table-column prop="original_filename" label="文件名"/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="open(row)">查看与复核</el-button></template></el-table-column></el-table>
    <el-drawer v-model="visible" title="回单复核与入账" size="min(920px, 96vw)"><article v-for="item in items" :key="item.id" class="receipt-card"><div class="receipt-state"><span>{{ item.source_filename }}</span><el-tag>{{ statusLabel(item.status) }}</el-tag></div><dl><div><dt>方向</dt><dd>{{ directionLabel(item.direction) }}</dd></div><div><dt>交易时间</dt><dd>{{ item.transaction_at || '待复核' }}</dd></div><div><dt>金额</dt><dd>¥ {{ item.amount || '-' }}</dd></div><div><dt>核心流水号</dt><dd>{{ item.bank_serial_number || '-' }}</dd></div></dl><p class="counterparty">付款方：{{ item.payer_name || '-' }}　收款方：{{ item.payee_name || '-' }}　摘要：{{ item.summary || '-' }}</p><el-alert v-if="item.error_message" :title="item.error_message" type="warning" :closable="false"/><el-table v-if="item.allocations?.length" :data="item.allocations" size="small" border class="allocation-table"><el-table-column label="合同类型" width="100"><template #default="{row}">{{ allocationTarget(row).type }}</template></el-table-column><el-table-column label="合同 ID"><template #default="{row}">{{ allocationTarget(row).id }}</template></el-table-column><el-table-column prop="amount" label="分摊金额"/><el-table-column prop="status" label="状态"/><el-table-column label="操作" width="120"><template #default="{row}"><el-button v-if="row.status==='draft'" link type="primary" @click="allocation(item,row)">编辑</el-button><el-button v-if="row.status==='draft'" link type="danger" @click="removeAllocation(item,row)">删除</el-button></template></el-table-column></el-table><div class="receipt-actions"><el-button @click="preview(item)">预览原始 PDF</el-button><el-button @click="review(item)" :disabled="!canEdit(item)">复核信息</el-button><el-button @click="allocation(item)" :disabled="!canEdit(item)">新增分摊</el-button><el-button type="primary" @click="confirm(item)" :disabled="item.status !== 'ready'">确认入账</el-button><el-button v-if="canEdit(item)" @click="ignore(item)">忽略</el-button><el-button v-if="item.status === 'failed'" @click="retry(item)">重新识别</el-button><el-button v-if="item.status === 'confirmed'" type="danger" plain @click="clear(item)">清除入账</el-button><el-button v-if="item.status === 'failed'" type="danger" plain @click="deleteFailed(item)">删除失败文件</el-button></div></article><el-empty v-if="!items.length" description="暂无回单"/></el-drawer>
    <el-dialog v-model="reviewVisible" title="复核回单" width="560px" append-to-body><el-form :model="reviewForm" label-width="90px"><el-form-item label="方向"><el-radio-group v-model="reviewForm.direction"><el-radio-button value="receipt">收款</el-radio-button><el-radio-button value="payment">付款</el-radio-button></el-radio-group></el-form-item><el-form-item label="交易时间"><el-date-picker v-model="reviewForm.transaction_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="金额"><el-input-number v-model="reviewForm.amount" :min="0.01" :precision="2" style="width:100%"/></el-form-item><el-form-item label="付款方"><el-input v-model="reviewForm.payer_name"/></el-form-item><el-form-item label="付款方账号"><el-input v-model="reviewForm.payer_account"/></el-form-item><el-form-item label="收款方"><el-input v-model="reviewForm.payee_name"/></el-form-item><el-form-item label="收款方账号"><el-input v-model="reviewForm.payee_account"/></el-form-item><el-form-item label="流水号"><el-input v-model="reviewForm.bank_serial_number"/></el-form-item><el-form-item label="摘要"><el-input v-model="reviewForm.summary"/></el-form-item></el-form><template #footer><el-button @click="reviewVisible=false">取消</el-button><el-button type="primary" @click="saveReview">保存复核</el-button></template></el-dialog>
    <el-dialog v-model="allocationVisible" title="回单分摊合同" width="560px" append-to-body><el-form :model="allocationForm" label-width="90px"><el-form-item label="合同"><el-select v-model="allocationForm.contract_key" filterable remote :remote-method="searchContracts" :loading="searching" placeholder="输入合同名称片段" style="width:100%"><el-option v-for="option in options" :key="contractKey(option)" :label="`[${option.contract_type}] ${option.contract_name} (${option.contract_code || '-'})`" :value="contractKey(option)"/></el-select></el-form-item><el-form-item label="分摊金额"><el-input-number v-model="allocationForm.amount" :min="0.01" :precision="2" style="width:100%"/></el-form-item></el-form><template #footer><el-button @click="allocationVisible=false">取消</el-button><el-button type="primary" @click="saveAllocation">保存分摊</el-button></template></el-dialog>
  </AppWorkspacePanel>
</template>
<script setup>
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'; import { ElMessage, ElMessageBox } from 'element-plus'; import AppWorkspacePanel from '@/components/ui/AppWorkspacePanel.vue'; import { clearReceipt, confirmReceipt, createReceiptAllocation, updateReceiptAllocation, deleteReceiptAllocation, deleteFailedReceipt, fetchReceiptFile, ignoreReceipt, listReceiptBatches, listReceiptItems, retryReceipt, reviewReceipt, searchReceiptContracts, uploadReceipt } from '@/api/bankReceipt'
const batches=ref([]),items=ref([]),visible=ref(false),reviewVisible=ref(false),allocationVisible=ref(false),current=ref(null),options=ref([]),searching=ref(false),selectedBatch=ref(null)
const statusFilter=ref(''),statusOptions=[{value:'uploaded',label:'已上传'},{value:'processing',label:'识别中'},{value:'completed',label:'待处理'},{value:'failed',label:'失败'}],filteredBatches=computed(()=>statusFilter.value?batches.value.filter(row=>row.status===statusFilter.value):batches.value)
const reviewForm=reactive({direction:'unknown',transaction_at:'',amount:0.01,payer_name:'',payer_account:'',payee_name:'',payee_account:'',bank_serial_number:'',summary:''}),allocationForm=reactive({id:null,contract_key:null,amount:0.01});let searchTimer
watch(reviewVisible, shown=>{if(shown&&current.value)Object.assign(reviewForm,{payer_name:current.value.payer_name||'',payer_account:current.value.payer_account||'',payee_name:current.value.payee_name||'',payee_account:current.value.payee_account||''})})
const load=async()=>{ batches.value=await listReceiptBatches() }; const refresh=async()=>{if(selectedBatch.value)items.value=await listReceiptItems(selectedBatch.value.id)};let pollTimer;onMounted(async()=>{await load();pollTimer=window.setInterval(async()=>{if(batches.value.some(row=>['uploaded','processing'].includes(row.status))){await load();await refresh()}},5000)});onUnmounted(()=>window.clearInterval(pollTimer))
const preview=async item=>{const win=window.open('about:blank','_blank');if(!win){ElMessage.error('请允许本站弹出窗口');return}try{const blob=await fetchReceiptFile(item.id);const url=URL.createObjectURL(blob);win.opener=null;win.location.replace(url);window.setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(error){win.close();throw error}}
const upload=async(file)=>{ await uploadReceipt(file.raw); ElMessage.success('回单已上传，正在识别'); await load() }; const open=async(row)=>{ selectedBatch.value=row; await refresh(); visible.value=true }; const canEdit=i=>['needs_review','ready','cleared'].includes(i.status);const directionLabel=v=>v==='receipt'?'收款':v==='payment'?'付款':'待判断';const statusLabel=v=>({needs_review:'待复核',ready:'待入账',confirmed:'已入账',cleared:'已清除',failed:'识别失败',ignored:'已忽略'}[v]||v)
const retry=async i=>{await retryReceipt(i.id);ElMessage.success('已重新提交识别');await refresh()}
const contractKey=v=>`${v.contract_type}:${v.contract_id??v.id}`;const mergeOptions=(...groups)=>{const merged=new Map();groups.flat().filter(Boolean).forEach(v=>merged.set(contractKey(v),{...v,id:v.contract_id??v.id}));return [...merged.values()].slice(0,20)}
const review=i=>{current.value=i;Object.assign(reviewForm,{direction:i.direction,transaction_at:i.transaction_at?.replace('Z','')||'',amount:Number(i.amount||0.01),bank_serial_number:i.bank_serial_number||'',summary:i.summary||''});reviewVisible.value=true};const saveReview=async()=>{await reviewReceipt(current.value.id,reviewForm);ElMessage.success('复核已保存');reviewVisible.value=false;await refresh()};const allocationTarget=row=>row.upstream_contract_id?{type:'上游',kind:'upstream',id:row.upstream_contract_id}:row.downstream_contract_id?{type:'下游',kind:'downstream',id:row.downstream_contract_id}:{type:'管理',kind:'management',id:row.management_contract_id};const allocation=(i,row=null)=>{current.value=i;const target=row?allocationTarget(row):null;Object.assign(allocationForm,{id:row?.id||null,contract_key:target?`${target.kind}:${target.id}`:null,amount:Number(row?.amount||i.amount||0.01)});options.value=mergeOptions(i.candidates||[],target?{contract_type:target.kind,id:target.id,contract_name:`已选合同 #${target.id}`} : []);allocationVisible.value=true};const searchContracts=q=>{window.clearTimeout(searchTimer);if(!q){options.value=mergeOptions(current.value?.candidates||[],options.value.find(v=>contractKey(v)===allocationForm.contract_key));return}searchTimer=window.setTimeout(async()=>{searching.value=true;try{const results=await searchReceiptContracts(q,current.value.direction);const selected=options.value.find(v=>contractKey(v)===allocationForm.contract_key);options.value=mergeOptions(current.value.candidates||[],selected,results)}finally{searching.value=false}},300)};const saveAllocation=async()=>{const target=options.value.find(v=>contractKey(v)===allocationForm.contract_key);if(!target){ElMessage.warning('请选择合同');return}const data={direction:current.value.direction,amount:allocationForm.amount};data[`${target.contract_type}_contract_id`]=target.id;if(allocationForm.id)await updateReceiptAllocation(current.value.id,allocationForm.id,data);else await createReceiptAllocation(current.value.id,data);ElMessage.success('分摊已保存');allocationVisible.value=false;await refresh()};const removeAllocation=async(i,row)=>{try{await ElMessageBox.confirm('确定删除这条草稿分摊？','删除分摊',{type:'warning'});await deleteReceiptAllocation(i.id,row.id);ElMessage.success('分摊已删除');await refresh()}catch{}};const confirm=async i=>{await confirmReceipt(i.id);ElMessage.success('回单已入账');await refresh()};const clear=async i=>{try{const r=await ElMessageBox.prompt('请输入清除原因','清除入账',{inputValidator:v=>v?.length>1});await clearReceipt(i.id,r.value);ElMessage.success('已清除入账');await refresh()}catch{}};const ignore=async i=>{try{const r=await ElMessageBox.prompt('请输入忽略原因','忽略回单',{inputValidator:v=>v?.length>1});await ignoreReceipt(i.id,r.value);ElMessage.success('回单已忽略');await refresh()}catch{}};const deleteFailed=async i=>{try{await ElMessageBox.confirm('仅删除识别失败且未入账的源文件。确定继续？','删除失败文件',{type:'warning'});await deleteFailedReceipt(i.id);ElMessage.success('失败文件已删除');await refresh()}catch{}}
</script>
<style scoped>.status-filter{display:flex;justify-content:flex-end;margin:14px 0}.receipt-card{padding:16px 0;border-bottom:1px solid var(--el-border-color-lighter)}.receipt-state,.receipt-actions{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.receipt-card dl{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:18px 0}.receipt-card dt,.counterparty{font-size:12px;color:#7c8998}.receipt-card dd{margin:4px 0 0;font-weight:600}.counterparty{margin:0 0 14px;overflow-wrap:anywhere}@media(max-width:640px){.receipt-card dl{grid-template-columns:repeat(2,1fr)}}</style>
